@ConfigGroup(TcgLockedConfig.GROUP)
public interface TcgLockedConfig extends Config
{
	String GROUP = "tcglocked";
	String SYNC_GROUP_COLLECTION = "syncGroupCollection";

	enum Enforcement
	{
		/** Remove the equip/use menu option for locked items (soft client-side block). */
		BLOCK,
		/** Leave the menu alone and warn when a locked action is attempted. */
		WARN_ONLY
	}

	enum Preset
	{
		GEAR_ONLY("Gear only"),
		GEAR_AND_TELEPORTS("Gear and teleports"),
		EVERYTHING("Everything"),
		CUSTOM("Custom");

		private final String label;

		Preset(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Locking",
		description = "What is locked and how",
		position = 0
	)
	String LOCKING = "locking";

	@ConfigSection(
		name = "Feedback",
		description = "What the plugin shows and plays",
		position = 1
	)
	String FEEDBACK = "feedback";

	@ConfigSection(
		name = "Advanced",
		description = "Starter allowances and overrides",
		position = 2,
		closedByDefault = true
	)
	String ADVANCED = "advanced";

	@ConfigItem(
		keyName = "preset",
		name = "Difficulty",
		description = "A one click difficulty. Choose Custom to control each lock below yourself.",
		section = LOCKING,
		position = 0
	)
	default Preset preset()
	{
		return Preset.GEAR_AND_TELEPORTS;
	}

	@ConfigItem(
		keyName = "deferToBronzeman",
		name = "Defer locking to Bronzeman TCG",
		description = "When the Bronzeman TCG plugin is enabled, let its restriction engine handle all locking "
			+ "(no double menu-stripping, padlocks or warnings from this plugin). The lockbook, unlock reveals "
			+ "and party features keep working. Turn off to enforce with both plugins at once.",
		section = LOCKING,
		position = 2
	)
	default boolean deferToBronzeman()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enforcement",
		name = "Enforcement",
		description = "Block: remove locked actions. Warn only: allow them and optionally warn in chat.",
		section = LOCKING,
		position = 1
	)
	default Enforcement enforcement()
	{
		return Enforcement.BLOCK;
	}

	@ConfigItem(
		keyName = "gateEquipment",
		name = "Lock equipment",
		description = "Require owning a card before you can Wield / Wear / Equip an item. Used when Difficulty is Custom.",
		section = LOCKING,
		position = 3
	)
	default boolean gateEquipment()
	{
		return true;
